/** STAGE 2: WHAT IS ASKED ONCE A DESIGN IS SELECTED. Experiment 159.
 *
 *  The refinement tables of `docs/research/study-design-decision-tree-2026-11-01.md`, carried as
 *  data so that a question, its caveats and its sentences are read in one place. That report holds
 *  the evidence and the strength of each; correct a question there and here together. The option
 *  wording is constructed and untested, which the report says for every table.
 *
 *  `SRC` is not in the report's tables. It is where surveillance went on 2026-11-01, when it
 *  left the list of designs: *"surveillance will be in stage 2 as a source"*. */
import type {ParamsByType} from './types.js';

export interface DesignOption {
  id:string;
  label:string;
  /** What choosing this carries. Shown once it is chosen. */
  caveat?:string;
  /** The sentence for the Methods note, with `‹slots›` for the practitioner to fill. */
  sentence?:string;
  /** "Not sure / not stated": a stated unknown, which is a different fact from no answer. */
  unknown?:boolean;
  /** What that unknown withholds, where the question names it. */
  reading?:string;
}
export interface DesignQuestion {
  id:string; section:string; text:string; options:DesignOption[];
  /** Several options may hold at once. */
  multi?:boolean;
}
/** `option` is one option id, or several separated by spaces where the question is `multi`. */
export interface DesignAnswer {option:string; fills?:Record<string,string>}

export interface DeclaredCell {
  /** What this cell counts. A cell and its total may count different things. */
  counts?:string;
  source?:string;
  /** Worked out from other cells rather than collected, so it has no source of its own. */
  derived?:boolean;
}

/** THE 2x2 THE DESIGN IS ABOUT, in the practitioner's words, declared before any data need exist.
 *  The practitioner, 2026-11-01: *"start mapping to ABCD as early as study design."* */
export interface DeclaredTable {
  exposed?:string; unexposed?:string; outcome?:string; noOutcome?:string;
  /** What exposure is known for, which describes the whole table. Exposure may be known only for
   *  places while the cells count the people in them. */
  exposureKnownFor?:string;
  /** What each cell and total holds, keyed by `TABLE_CELLS`. Words and never counts: a study not
   *  yet begun has none, and the practitioner said so on 2026-11-01, reading this page. */
  cells?:Record<string,DeclaredCell>;
}

/** A DESIGN IS A STATEMENT ABOUT WHICH TOTALS THE STUDY FIXED, which is why it licenses what it
 *  does. Only the two designs South London declares, for now: the practitioner, 2026-11-01, "One
 *  at a time, South London first." `note` says what the table cannot show on its face. */
export const DESIGN_TABLES:Partial<Record<string,{fixed:'rows'|null;note:string}>>={
  'cohort':{fixed:'rows',note:'A cohort fixes the row totals: the groups it followed. So a/(a+b) is a risk.'},
  'ecological':{fixed:null,note:'Exposure is known only for groups, so name each row as the group it '
    +'is. Nobody in a row is known to have been exposed, and the comparison is between groups.'},
};
export const TABLE_CELLS=['a','b','a+b','c','d','c+d'] as const;

/** Is this cell described? It needs what it counts, and a source unless it was worked out. */
export const cellDescribed=(cell?:DeclaredCell):boolean=>
  Boolean(cell?.counts?.trim()&&(cell.derived||cell.source?.trim()));

const joined=(keys:readonly string[]):string=>keys.length<2?keys[0]!
  :`${keys.slice(0,-1).join(', ')} and ${keys[keys.length-1]}`;

/** Cells that share a description read once, which is what makes six cells one short paragraph. */
function grouped(table:DeclaredTable,valueOf:(cell:DeclaredCell)=>string|undefined):[string,string[]][]{
  const groups=new Map<string,string[]>();
  for(const key of TABLE_CELLS){
    const value=table.cells?.[key]?valueOf(table.cells[key]!)?.trim():'';
    if(value)groups.set(value,[...(groups.get(value)??[]),key]);
  }
  return [...groups];
}

export function tableSentences(table?:DeclaredTable):string[]{
  if(!table)return [];
  const named=table.exposed?.trim()&&table.unexposed?.trim()&&table.outcome?.trim()
    ?[`Exposed was ${table.exposed!.trim()}, unexposed was ${table.unexposed!.trim()}, and the `
      +`outcome was ${table.outcome!.trim()}.`]:[];
  const known=table.exposureKnownFor?.trim()?[`Exposure was known for ${table.exposureKnownFor.trim()}.`]:[];
  const counted=grouped(table,c=>c.counts).map(([what,keys])=>
    `${joined(keys)} ${keys.length>1?'count':'counts'} ${what}.`);
  const from=grouped(table,c=>c.derived?undefined:c.source).map(([source,keys])=>
    `${joined(keys)} came from ${source}.`);
  const worked=grouped(table,c=>c.derived?'yes':undefined).map(([,keys])=>
    `${joined(keys)} ${keys.length>1?'were':'was'} worked out from other cells.`);
  return [...named,...known,...counted,...from,...worked];
}

